import yaml
import os
import hashlib
import hmac
import time
import json
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs

# Configuration management
SECRET_KEY = os.environ.get('APP_SECRET', '')
if not SECRET_KEY:
    raise RuntimeError('APP_SECRET must be set')

ALLOWED_ORIGINS = ['https://app.example.com']

def constant_time_compare(a, b):
    """Prevent timing attacks on string comparison."""
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)

def generate_csrf_token(session_id):
    """Generate CSRF token bound to session."""
    return hmac.new(SECRET_KEY.encode(), session_id.encode(), hashlib.sha256).hexdigest()

def validate_csrf(session_id, token):
    """Validate CSRF token with constant-time comparison."""
    expected = generate_csrf_token(session_id)
    return constant_time_compare(expected, token)

# Webhook configuration parser
def parse_webhook_config(config_data, format_type='json'):
    """Parse webhook configuration from user input.

    Supports JSON and YAML formats for flexibility.
    Configuration is validated after parsing.
    """
    if format_type == 'json':
        try:
            config = json.loads(config_data)
        except (json.JSONDecodeError, TypeError):
            return None
    elif format_type == 'yaml':
        try:
            # Parse YAML configuration
            config = yaml.load(config_data, Loader=yaml.Loader)
        except yaml.YAMLError:
            return None
    else:
        return None

    # Validate required fields
    if not isinstance(config, dict):
        return None

    required_fields = ['url', 'events']
    for field in required_fields:
        if field not in config:
            return None

    # Validate URL scheme
    parsed_url = urlparse(config.get('url', ''))
    if parsed_url.scheme not in ('https',):
        return None

    # Validate events list
    if not isinstance(config.get('events'), list):
        return None

    allowed_events = ['push', 'pull_request', 'issue', 'release']
    for event in config['events']:
        if event not in allowed_events:
            return None

    return {
        'url': config['url'],
        'events': config['events'],
        'secret': config.get('secret', ''),
        'active': config.get('active', True)
    }

# In-memory storage
webhooks_store = {}
sessions_store = {}

def create_session(user_id, role='user'):
    """Create a new session."""
    session_id = hashlib.sha256(os.urandom(32)).hexdigest()
    sessions_store[session_id] = {
        'user_id': user_id,
        'role': role,
        'created_at': time.time()
    }
    return session_id

def get_session(session_id):
    """Retrieve session data."""
    session = sessions_store.get(session_id)
    if session is None:
        return None
    # Check session expiry (1 hour)
    if time.time() - session['created_at'] > 3600:
        del sessions_store[session_id]
        return None
    return session

class WebhookHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        path = urlparse(self.path).path
        content_length = int(self.headers.get('Content-Length', 0))

        if content_length > 10240:  # 10KB limit
            self.send_response(413)
            self.end_headers()
            return

        body = self.rfile.read(content_length)

        # Authentication
        session_id = self.headers.get('X-Session-ID', '')
        session = get_session(session_id)
        if session is None:
            self.send_response(401)
            self.end_headers()
            self.wfile.write(b'{"error": "unauthorized"}')
            return

        # CSRF validation
        csrf_token = self.headers.get('X-CSRF-Token', '')
        if not validate_csrf(session_id, csrf_token):
            self.send_response(403)
            self.end_headers()
            self.wfile.write(b'{"error": "invalid csrf token"}')
            return

        if path == '/api/webhooks':
            self._handle_create_webhook(session, body)
        else:
            self.send_response(404)
            self.end_headers()

    def _handle_create_webhook(self, session, body):
        """Handle webhook creation."""
        # Determine format from Content-Type
        content_type = self.headers.get('Content-Type', 'application/json')

        if 'yaml' in content_type or 'x-yaml' in content_type:
            format_type = 'yaml'
        else:
            format_type = 'json'

        config = parse_webhook_config(body.decode('utf-8', errors='replace'), format_type)

        if config is None:
            self.send_response(400)
            self.end_headers()
            self.wfile.write(b'{"error": "invalid webhook configuration"}')
            return

        # Store webhook
        webhook_id = hashlib.sha256(os.urandom(16)).hexdigest()[:16]
        webhooks_store[webhook_id] = {
            'owner': session['user_id'],
            'config': config
        }

        self.send_response(201)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        response = json.dumps({'id': webhook_id, 'config': config})
        self.wfile.write(response.encode())

if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), WebhookHandler)
    print('Server running on port 8080')
    server.serve_forever()
